int unicode_table_codepoints() { return 0x110000; }

int width_chunk_count() { return static_cast<int>(kWidthChunkCount); }

const ChunkDesc* width_chunks() { return kWidthChunks; }

const CpRecord* width_record(std::uint32_t cp) {
  if (cp > 0x10FFFFu) return nullptr;
  std::size_t lo = 0;
  std::size_t hi = kWidthChunkCount;
  while (lo + 1 < hi) {
    const std::size_t mid = (lo + hi) / 2;
    if (kWidthChunks[mid].first <= cp) {
      lo = mid;
    } else {
      hi = mid;
    }
  }
  const ChunkDesc& desc = kWidthChunks[lo];
  if (cp < desc.first || cp - desc.first >= desc.count) return nullptr;
  return &desc.rows[cp - desc.first];
}

int unicode_width(std::uint32_t cp) {
  const CpRecord* rec = width_record(cp);
  return rec == nullptr ? 1 : static_cast<int>(rec->width);
}

int unicode_category_id(std::uint32_t cp) {
  const CpRecord* rec = width_record(cp);
  return rec == nullptr ? 2 : static_cast<int>(rec->cat);
}

const char* unicode_category(std::uint32_t cp) {
  const int id = unicode_category_id(cp);
  if (id < 0 || static_cast<std::size_t>(id) >= kCategoryCount) return kCategoryNames[2];
  return kCategoryNames[id];
}

